local _, Private = ...
local L = Private.L

local LibStub = LibStub

-- Runs after successful profile import
local function CallbackFunction(accepted, name)
	if not accepted then return end

	-- 1080p
	local scaled = Private.Addon.db.global.scaled

	-- Handle minimap icon
	local LDBI = LibStub('LibDBIcon-1.0')
	BigWigsIconDB.hide = true
	LDBI:Hide('BigWigs')

	-- 1080p: X -489, Y -514
	-- 1440p: X -709, Y -694
	if scaled then
		local bres = BigWigs3DB.namespaces.BigWigs_Plugins_BattleRes
		if bres and bres.profiles and bres.profiles[name] then
			bres.profiles[name].position = { nil, nil, -489, -514 }
		end
	end
end

-- BigWigs profiles
function Private:Setup_BigWigs(layout)
	if not BigWigsAPI then Private:Print('BigWigs ' .. L["is not installed or enabled."]) return end

	-- Profile names
	local name_main = 'Luckyone Main'
	local name_healing = 'Luckyone Healing'

	-- Profile strings
	local profile_main = [[BW2:]]
	local profile_healing = [[BW2:]]

	-- Profile import
	local name = (layout == 'main' and name_main) or name_healing
	BigWigsAPI.RegisterProfile('LuckyoneUI', (layout == 'main' and profile_main) or profile_healing, name, function(accepted) CallbackFunction(accepted, name) end)
end
